-- Filet de sécurité : toute URL restée en double est retirée (ordre conservé).
UPDATE publications p SET images = COALESCE((
  SELECT string_agg(u, ',' ORDER BY ord) FROM (
    SELECT u, min(ord) AS ord
    FROM unnest(string_to_array(p.images, ',')) WITH ORDINALITY AS t(u, ord)
    WHERE u <> '' GROUP BY u
  ) s
), p.images)
WHERE p.type = 'place' AND p.images IS NOT NULL AND p.images <> '';

